import { headers } from 'next/headers';

async function getUserPreferences() {
  const headersList = await headers();
  const host = headersList.get('x-forwarded-host') || headersList.get('host') || 'localhost:3000';
  const proto = headersList.get('x-forwarded-proto') || 'http';
  const baseUrl = `${proto}://${host}`;

  const res = await fetch(`${baseUrl}/api/user/preferences`, {
    cache: 'no-store'
  });

  if (!res.ok) {
    throw new Error('Failed to fetch user preferences');
  }

  return res.json();
}

export default async function UserDashboard() {
  const preferences = await getUserPreferences();

  return (
    <div>
      <h2>User Dashboard</h2>
      <div>
        <h3>Your Preferences</h3>
        <ul>
          <li>Theme: {preferences.theme}</li>
          <li>Language: {preferences.language}</li>
          <li>Notifications: {preferences.notifications ? 'Enabled' : 'Disabled'}</li>
          <li>Last updated: {preferences.updatedAt}</li>
        </ul>
      </div>
    </div>
  );
}

